/**
 * Teardown annotation content.
 *
 * Single source of truth for all engineering annotations shown when
 * teardown mode is active. Each section's entries are generated by a
 * factory function that accepts computed values from the component,
 * so the content stays centralized while dynamic data is injected
 * type-safely.
 *
 * To add or edit teardown text for any visualization, change it here.
 * Components import these factories and pass the result to TeardownPanel.
 */

export type TeardownEntry = {
  label: string;
  value: string;
};

